const crypto = require('crypto');
const secreto = $env.N8N_WEBHOOK_SECRET;
const entrada = $input.first().json;

// Sin secreto configurado se deja pasar, para no romper una instalacion de
// pruebas; en produccion la variable debe estar puesta en ambos lados.
if (!secreto) {
  return [{ json: { ...entrada, firma_valida: null } }];
}

const recibida = (entrada.headers || {})['x-signature-256'] || '';
// Hay que reproducir EXACTAMENTE la cadena que firmo la API. Del lado de Python
// es json.dumps(sort_keys=True, separators=(',',':'), ensure_ascii=False). El
// replacer-array de JSON.stringify ordena las claves; sin espacios ya no pone.
const cuerpo = JSON.stringify(entrada.body, Object.keys(entrada.body).sort());
const esperada = 'sha256=' + crypto.createHmac('sha256', secreto).update(cuerpo, 'utf8').digest('hex');

// Comparacion en tiempo constante: un === filtra el secreto por temporizacion.
const a = Buffer.from(recibida);
const b = Buffer.from(esperada);
const valida = a.length === b.length && crypto.timingSafeEqual(a, b);

if (!valida) {
  throw new Error('Firma HMAC invalida: la notificacion no viene de la API');
}
return [{ json: { ...entrada, firma_valida: true } }];

