={{ (() => {
  const t = $json.body;
  const iconos = { Frustrado: '\uD83D\uDE20', Urgente: '\uD83D\uDEA8', Neutral: '\uD83D\uDCAC', Satisfecho: '\uD83D\uDE42' };
  const icono = iconos[t.sentimiento] || '\u26A0\uFE0F';
  const lineas = [
    icono + ' *Ticket prioritario*',
    '',
    '*' + (t.titulo || 'Sin titulo') + '*',
    (t.descripcion || '').slice(0, 300),
    '',
    '\uD83C\uDFF7 Categoria: ' + (t.categoria || '?'),
    '\uD83D\uDCC8 Prioridad: ' + (t.prioridad || '?') + '  |  Tono: ' + (t.sentimiento || '?'),
  ];
  // Solo se muestra la confianza si clasifico la IA: el motor de reglas no la estima.
  if (t.clasificado_por === 'llm') {
    lineas.push('\uD83E\uDD16 IA: ' + Math.round((t.confianza_ia || 0) * 100) + '% de confianza');
    if (t.requiere_revision) lineas.push('\u2757 Confianza baja: conviene revisar la clasificacion');
  } else {
    lineas.push('\u2699\uFE0F Clasificado por reglas (la IA no estaba disponible)');
  }
  if (t.url) { lineas.push(''); lineas.push('\uD83D\uDD17 ' + t.url); }
  return lineas.join('\n');
})() }}
